#!/usr/bin/env python3
import sys
import openpyxl

def main():
    src_path = sys.argv[1]
    out_path = sys.argv[2]

    wb = openpyxl.load_workbook(src_path)
    ws = wb["Sheet1"]

    # Collect the color list from column D (skip header row D2="Colour").
    colors = []
    row = 2
    while True:
        val = ws.cell(row=row, column=4).value  # column D = 4
        if val is None:
            break
        s = str(val).strip()
        if s and s.lower() != "colour":
            colors.append(s)
        row += 1

    # Deduplicate colors case-insensitively.
    color_map = {}
    for c in colors:
        key = c.lower()
        if key not in color_map:
            color_map[key] = c
    unique_colors = list(color_map.values())

    # Process answer range B2:B17 based on column A.
    for r in range(2, 18):
        a_val = ws.cell(row=r, column=1).value
        result = ""
        if a_val is not None:
            needle = str(a_val).strip().lower()
            for col in unique_colors:
                if col.lower() in needle:
                    result = col
                    break
        ws.cell(row=r, column=2).value = result if result else ""

    wb.save(out_path)
    print("Done ->", out_path)

if __name__ == "__main__":
    main()
